def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_unknown_customer_is_404(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_customer_with_no_orders_has_empty_list(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_orders_are_newest_first_with_status(shop):
    first = order(shop, "c1", ("BOOK", 1)).body["order_id"]
    second = order(shop, "c1", ("PEN", 2)).body["order_id"]
    third = order(shop, "c1", ("LAMP", 1)).body["order_id"]
    shop.orders.handle_cancel(second)

    body = shop.insights.handle_order_history("c1").body
    assert [o["order_id"] for o in body["orders"]] == [third, second, first]
    assert [o["status"] for o in body["orders"]] == ["placed", "cancelled", "placed"]


def test_other_customers_orders_are_excluded(shop):
    order(shop, "c1", ("BOOK", 1))
    mine = order(shop, "c2", ("PEN", 1)).body["order_id"]
    body = shop.insights.handle_order_history("c2").body
    assert [o["order_id"] for o in body["orders"]] == [mine]


def test_totals_match_order_summary_including_discount(shop):
    # 4 x 6000 = 24000 subtotal: over the threshold, so gold gets 15% off.
    placed = order(shop, "c2", ("LAMP", 4)).body["order_id"]
    summary = shop.orders.handle_get(placed).body

    entry = shop.insights.handle_order_history("c2").body["orders"][0]
    assert entry == {"order_id": placed, "status": "placed", "total_cents": summary["total_cents"]}
    assert entry["total_cents"] == 24_000 - 3_600


def test_standard_discount_applies_in_history(shop):
    placed = order(shop, "c1", ("BOOK", 4)).body["order_id"]  # 10000 subtotal -> 10% off
    entry = shop.insights.handle_order_history("c1").body["orders"][0]
    assert entry["order_id"] == placed
    assert entry["total_cents"] == 9_000


def test_cancelled_orders_keep_their_total(shop):
    placed = order(shop, "c1", ("BOOK", 4)).body["order_id"]
    shop.orders.handle_cancel(placed)
    entry = shop.insights.handle_order_history("c1").body["orders"][0]
    assert entry == {"order_id": placed, "status": "cancelled", "total_cents": 9_000}


